/**
 * Tier-2 date and date/time builders for the calc DSL.
 *
 * The platform's calc grammar treats DATE and DATETIME as distinct
 * brands — DATE is calendar date (no time component), DATETIME is
 * instant-in-time. Knowhere accepts either brand for date-part extraction
 * and DATETIME_TRUNC.
 *
 * Constrained string arguments are typed as literal unions so the
 * agent gets autocomplete and compile-time validation:
 *   - `dateDif` unit: 'S' | 'MIN' | 'H' | 'Y' | 'M' | 'D'
 *   - `dateTimeTrunc` precision: a date-part literal union
 *   - `weekday` mode: 1 | 2 | 3
 */
import { coerce, makeComposedExpr, makeExpr, emitStringLiteral } from "./runtime.js";
// ---------------------------------------------------------------------------
// Constructors
// ---------------------------------------------------------------------------
/** Current instant. Wire `NOW()`. Returns DATETIME. */
export function now() {
    return makeExpr("datetime", () => `NOW()`);
}
/**
 * Build a DATE from numeric year / month / day components.
 * Wire `DATE(year, month, day)`. The `make` prefix avoids colliding
 * with the JS `Date` global if someone destructures `calc`.
 */
export function makeDate(year, month, day) {
    const y = coerce(year);
    const m = coerce(month);
    const d = coerce(day);
    return makeComposedExpr("date", [y, m, d], () => `DATE(${y.toCalcString()}, ${m.toCalcString()}, ${d.toCalcString()})`);
}
/**
 * Build a DATETIME from numeric date and time components.
 * Wire `DATETIME(year, month, day, hour, minute, second)`.
 */
export function dateTime(...values) {
    const [year, month, day, hour, minute, second] = values;
    const parts = [year, month, day, hour, minute, second].map((part) => coerce(part));
    return makeComposedExpr("datetime", parts, () => `DATETIME(${parts.map((part) => part.toCalcString()).join(", ")})`);
}
/**
 * Parse a text expression into a DATE. The server accepts ISO-style
 * `YYYY-MM-DD` literals; with a text expression as input the server
 * does a TRY_CAST and returns null on parse failure.
 */
export function dateValue(value) {
    const v = coerce(value);
    return makeComposedExpr("date", [v], () => `DATEVALUE(${v.toCalcString()})`);
}
// ---------------------------------------------------------------------------
// DATEDIF — difference between two dates/datetimes, in the specified unit.
// ---------------------------------------------------------------------------
/** Discoverable unit codes accepted by the wire `DATEDIF` function. */
export const dateDifUnit = {
    seconds: "S",
    minutes: "MIN",
    hours: "H",
    years: "Y",
    months: "M",
    days: "D",
};
/** Human-readable date difference units accepted by {@link dateDiff}. */
export const dateDiffUnit = {
    seconds: "seconds",
    minutes: "minutes",
    hours: "hours",
    years: "years",
    months: "months",
    days: "days",
};
const DATE_DIFF_UNIT_WIRE = {
    seconds: "S",
    minutes: "MIN",
    hours: "H",
    years: "Y",
    months: "M",
    days: "D",
};
/**
 * Difference between `end` and `start` in the specified unit.
 * - `'S'` — seconds; `'MIN'` — minutes; `'H'` — hours
 * - `'D'` — days; `'M'` — months; `'Y'` — years
 */
/** @deprecated Prefer {@link dateDiff} with human-readable units. */
export function dateDif(start, end, unit) {
    const s = coerce(start);
    const e = coerce(end);
    return makeComposedExpr("number", [s, e], () => `DATEDIF(${s.toCalcString()}, ${e.toCalcString()}, ${emitStringLiteral(unit)})`);
}
/** Difference between two dates using a readable unit name. */
export function dateDiff(start, end, unit) {
    return dateDif(start, end, DATE_DIFF_UNIT_WIRE[unit]);
}
// ---------------------------------------------------------------------------
// DATETIME_TRUNC — truncate a datetime to the given precision.
// ---------------------------------------------------------------------------
/** Discoverable precision values accepted by `DATETIME_TRUNC`. */
export const dateTimeTruncPrecision = {
    microseconds: "MICROSECONDS",
    milliseconds: "MILLISECONDS",
    second: "SECOND",
    minute: "MINUTE",
    hour: "HOUR",
    day: "DAY",
    week: "WEEK",
    month: "MONTH",
    quarter: "QUARTER",
    year: "YEAR",
    decade: "DECADE",
    century: "CENTURY",
    millennium: "MILLENNIUM",
};
const DATE_TIME_PRECISION_WIRE = {
    microseconds: "MICROSECONDS",
    milliseconds: "MILLISECONDS",
    second: "SECOND",
    minute: "MINUTE",
    hour: "HOUR",
    day: "DAY",
    week: "WEEK",
    month: "MONTH",
    quarter: "QUARTER",
    year: "YEAR",
    decade: "DECADE",
    century: "CENTURY",
    millennium: "MILLENNIUM",
};
/**
 * Truncate a DATE or DATETIME to the given precision. E.g.
 * `dateTimeTrunc(t, "MONTH")` returns the first instant of `t`'s month.
 */
/** @deprecated Prefer {@link truncateDateTime} with human-readable precision. */
export function dateTimeTrunc(value, precision) {
    const v = coerce(value);
    return makeComposedExpr("datetime", [v], () => `DATETIME_TRUNC(${v.toCalcString()}, ${emitStringLiteral(precision)})`);
}
/** Truncate a date/datetime using a readable precision name. */
export function truncateDateTime(value, precision) {
    return dateTimeTrunc(value, DATE_TIME_PRECISION_WIRE[precision]);
}
// ---------------------------------------------------------------------------
// WEEKDAY — day-of-week as a number, with optional mode.
// ---------------------------------------------------------------------------
/**
 * Modes accepted by the wire `WEEKDAY` function.
 *   - 1 — Sunday=1 .. Saturday=7  (default)
 *   - 2 — Monday=1 .. Sunday=7
 *   - 3 — Monday=0 .. Sunday=6
 */
export const weekdayMode = {
    sundayOne: 1,
    mondayOne: 2,
    mondayZero: 3,
};
/**
 * Day-of-week as a numeric, optionally selecting the numbering scheme.
 */
export function weekday(value, mode) {
    const v = coerce(value);
    if (mode === undefined) {
        return makeComposedExpr("number", [v], () => `WEEKDAY(${v.toCalcString()})`);
    }
    const wireMode = typeof mode === "string" ? weekdayMode[mode] : mode;
    return makeComposedExpr("number", [v], () => `WEEKDAY(${v.toCalcString()}, ${wireMode})`);
}
// ---------------------------------------------------------------------------
// Date-part extraction — all six functions accept date|datetime in Knowhere.
// ---------------------------------------------------------------------------
/** Year component as NUMBER. */
export function year(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `YEAR(${v.toCalcString()})`);
}
/** Month component (1–12) as NUMBER. */
export function month(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `MONTH(${v.toCalcString()})`);
}
/** Day-of-month (1–31) as NUMBER. */
export function day(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `DAY(${v.toCalcString()})`);
}
/** Hour (0–23) from a DATE or DATETIME. */
export function hour(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `HOUR(${v.toCalcString()})`);
}
/** Minute (0–59) from a DATE or DATETIME. */
export function minute(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `MINUTE(${v.toCalcString()})`);
}
/** Second (0–59) from a DATE or DATETIME. */
export function second(value) {
    const v = coerce(value);
    return makeComposedExpr("number", [v], () => `SECOND(${v.toCalcString()})`);
}
